import scala.util.{Try, Using}

val lines: Try[Seq[String]] =
  Using(new BufferedReader(new FileReader("file.txt"))) { reader =>   // acquire + use
    Iterator.continually(reader.readLine()).takeWhile(_ != null).toSeq
  }                                  // released on success and failure, reverse order

Using.Manager { use =>               // several resources, one scope
  val in = use(new FileReader("a")); val out = use(new FileWriter("b"))
  copy(in, out)
}
